docs.body:
Resolve unfamiliar datasets by path or title, then use the returned
`uniqueId`. When you don't know the exact name, **search first** --
`project.search` takes a case-insensitive substring and covers every
entity type (datasets by title/alias/units; groups, actions, sources,
workspaces, tables by title):

```
// Discovery: partial name -> compact typed rows with ids and paths
project.search { query: "pressure" }
project.search { query: "psia", type: "dataset" }

// One group's contents without the full project. Accepts EITHER id
// space: positional groupId, or uniqueId (what workspace refs carry
// under the key "groupId" -- any suspiciously large "groupId" is one).
project.group.get { uniqueId: 614 }

// Exact lookup once you know the name/path
project.dataset.getByPath { path: "Audio/Channel A" }
project.dataset.getByTitle { title: "Channel A", groupId: 0 }
project.dataset.getByUniqueId { uniqueId: 10001 }
assistant.dataset.resolve { path: "Audio/Channel A" }

// Inside transforms / canvas scripts: read peers via the API
const v = datasetGetFinal(uid)        // uid from the response above
```

`project.dataset.list`, `project.group.list`'s `datasetSummary`, and
`project.snapshot` all return `uniqueId` on every dataset. Duplicating
a dataset (or group) allocates a fresh `uniqueId`, so a copy is
distinguishable from the original.

```
project.dataset.addMany {
  groupId:      0,
  count:        40,
  options:      0,                   // bitfield, OR an array of slugs
                                     //   ["plot","fft"]  -> 1|2 = 3
                                     // bits: 1=Plot, 2=FFT, 4=Bar, 8=Gauge,
                                     //       16=Compass, 64=Waterfall (Pro),
                                     //       128=Meter. 32 enables nothing.
                                     // Lights: groupId must be a group created with
                                     // project.group.add{widgetType: 11} (LEDPanel);
                                     // there is no LED option bit.
  titlePattern: "LED {n}",           // {n} -> startNumber + i, {i} -> 0-based
  startNumber:  1,                   // optional, default 1
  startIndex:   1                    // optional: -1 = auto-assign next slot,
                                     // 0 = leave unset, 1+ = consecutive slots
}
```

## The SerialStudio SDK (natural API wrappers)

Every script engine (control loop, frame parser, transforms) has a generated
`SerialStudio` library on top of the raw `apiCall(method, params)` gateway. It
turns verbose calls into natural, positional ones:

```javascript
// Instead of:
apiCall("io.ble.writeCharacteristic", { characteristicUuid: "fff1", data: "<base64>" });

// Write:
io.ble.writeCharacteristic("fff1", "5600030C", SerialStudio.Hex);
```

Rules of the SDK:

Canonical communication-loss watchdog (tables + refreshDashboard):

```javascript
var commLost = false;

function loop() {
  var r = io.getLatestFrame();
  var hasData = r.ok && r.result.hasData;
  var stale   = hasData && r.result.ageMs > 1000;
  var fresh   = hasData && r.result.ageMs <= 1000;

if (stale && !commLost) {
    commLost = true;
    tableSet("BRD-1", "boot_selftest", 0xCC);  // transforms map 0xCC -> "Comm Loss"
    refreshDashboard();                        // render it without waiting for a frame
    notifyCritical("Watchdog", "No frames for " + r.result.ageMs + " ms");
  } else if (fresh && commLost) {
    commLost = false;
    notifyInfo("Watchdog", "Communication restored");
  }

delay(100);
}
```

Canonical auto-dashboard loop:

```javascript
function loop() {
  var f = newFrame();
  if (!f) { delay(100); return; }

var spec = { title: "Telemetry", widget: "multiplot", datasets: [] };
  for (var i = 0; i < f.values.length; ++i)
    spec.datasets.push({ title: "Channel " + (i + 1), index: i + 1, plot: true });

ensureDashboard([spec]);
  delay(100);
}
```

Rules: always pace a loop with `delay()` (50-250 ms for polling; ~20 ms floor for
dashboard-feeding simulations — every `tableSet`/`apiCall` is a blocking GUI-thread
hop, and a free-running loop that writes on each pass stalls the dashboard); do not
hand-roll exists-checks with `project.group.list` loops (ensureDashboard does
the diff); renaming a generated group in the editor makes the script recreate
it under the original title (the spec is the source of truth); ConsoleOnly mode
yields `text` but an empty `values`.

## Worked example: testo 549i BLE pressure probe (canonical)

A real pattern for a split read/write BLE probe (service `FFF0`, write `FFF1`,
notify `FFF2`) that streams only after a vendor command sequence. The service
and notify characteristic are set on the source and saved in the project, so the
control loop is just the handshake; a binary frame parser turns the
notifications into datasets.

Control loop (handshake only):

```javascript
const WRITE_UUID  = "fff1";
const ENABLE_CMDS = ["5600030000000C69023E81", "200000000000077B", "110000000000035A"];

function setup() {
  for (var i = 0; i < ENABLE_CMDS.length; ++i) {
    if (!io.ble.writeCharacteristic(WRITE_UUID, ENABLE_CMDS[i], SerialStudio.Hex).ok) return;
    delay(100);
  }
}

```javascript
function floatLE(frame, at) {
  var v = new DataView(new ArrayBuffer(4));
  for (var i = 0; i < 4; ++i) v.setUint8(i, frame[at + i] & 0xff);
  return v.getFloat32(0, true);
}
function markerEnd(frame, name) {
  for (var i = 0; i + name.length <= frame.length; ++i) {
    var hit = true;
    for (var j = 0; j < name.length; ++j)
      if (frame[i + j] !== name.charCodeAt(j)) { hit = false; break; }
    if (hit) return i + name.length;
  }
  return -1;
}
var bar = 0, psi = 0, batt = 0;
function parse(frame) {
  var p = markerEnd(frame, "DifferentialPressure");
  if (p !== -1 && p + 4 <= frame.length) { bar = floatLE(frame, p) * 1e-5; psi = bar * 14.5037738; }
  var b = markerEnd(frame, "BatteryLevel");
  if (b !== -1 && b + 4 <= frame.length) batt = floatLE(frame, b);
  return [bar, psi, batt];
}
```

### Mandatory step before `addWidget`

After flipping `setOptions` and BEFORE calling `addWidget`, set the matching
min/max for every visualization you just enabled. One `dataset.update` call
can carry all three pairs:

```
project.dataset.update {
  groupId: <gid>, datasetId: <did>,
  pltMin: -1.0, pltMax: 1.0,         // Plot/MultiPlot Y-axis
  wgtMin:  0.0, wgtMax: 100.0,       // Gauge/Bar scale
  fftMin: -1.0, fftMax: 1.0          // FFT/Waterfall expected input range
                                     //  (so the FFT can normalize the signal
                                     //   to [-1, +1] before windowing). Use
                                     //   the actual range of your raw
                                     //   samples, NOT a dB scale.
}
```

Manual path, when you need exact low-level control:

```
// 1. Find the dataset by path, or via snapshot.
project.dataset.getByPath { path: "Audio/Channel A" }
  -> { groupId, datasetId, uniqueId, ... }

// 2. Enable all three visualizations on the dataset in one shot.
project.dataset.setOptions {
  groupId: <gid>,
  datasetId: <did>,
  options: ["plot", "fft", "waterfall"]
}

// 3. Set the min/max ranges for EACH visualization family.
//    Plot + FFT + Waterfall = both pltMin/Max AND fftMin/Max.
//    fftMin/fftMax are the EXPECTED RAW INPUT RANGE for the FFT to
//    normalize against ([-1, +1] after normalization), NOT a dB axis.
//    Skip this and you'll see flat 0..0 axes. Note the abbreviated write-side
//    names: pltMin (not plotMin), wgtMin (not widgetMin) -- API silently
//    drops the full-name form.
project.dataset.update {
  groupId: <gid>, datasetId: <did>,
  pltMin: -1.0, pltMax: 1.0,           // time-domain Y-axis
  fftMin: -1.0, fftMax: 1.0,           // expected raw amplitude range
                                       //  (e.g. -32768..32767 for raw 16-bit
                                       //   audio, or -1..+1 for normalized)
  fftSamples: 1024, fftSamplingRate: 48000
}

// 4. Customize mode is required for any workspace edit.
project.workspace.setCustomizeMode { enabled: true }

// 5. Create the workspace.
project.workspace.add { title: "Signal Analysis",
                        icon: "qrc:/icons/panes/dashboard.svg" }
// -> { id: <wsId> }

// 6. Pin all three tiles. Omit relativeIndex; the API auto-assigns.
project.workspace.addWidget { workspaceId: <wsId>, widgetType: "plot",
                              groupId: <gid> }
project.workspace.addWidget { workspaceId: <wsId>, widgetType: "fft",
                              groupId: <gid> }
project.workspace.addWidget { workspaceId: <wsId>, widgetType: "waterfall",
                              groupId: <gid> }

// 7. Verify min/max landed (read the FULL-name keys, not the abbreviated
//    write-form). Re-snapshot or getByPath; pltMin/pltMax appear as
//    plotMin/plotMax in the response.
project.dataset.getByPath { path: "Audio/Channel A" }
  -> { plotMin: -1.0, plotMax: 1.0, fftMin: -1.0, fftMax: 1.0, ... }  -- good
```

The slug form (`widgetType: "plot"`) makes the addWidget vs setOption
numbering collision impossible. Integers still work for back-compat
(`widgetType: 9` is DashboardPlot), but the slugs are unambiguous.

## Recipe: Add a Gauge tile to an existing group

Goal: a group has one numeric dataset that you want to show as a radial
gauge on the executive workspace.

```
// 1. Pre-flight: project.snapshot returns sources + groups + workspaces
//    in one call.
project.snapshot
  -> note groupId (e.g. 0), compatibleWidgetTypeSlugs (e.g. ["plot"]),
     and the workspaceId for "Executive Overview" (e.g. 5001)

// 2. "gauge" isn't compatible yet. Flip Gauge on the dataset,
//    preserving Plot -- pass the COMPLETE list of options you want on.
project.dataset.setOptions {
  groupId: 0,
  datasetId: 0,
  options: ["plot", "gauge"]
}

// 3. VERIFY. Read the group again; compatibleWidgetTypeSlugs must
//    include "gauge".
project.group.list
  -> compatibleWidgetTypeSlugs: ["plot", "gauge"]  -- good

// 4. Set BOTH min/max pairs -- pltMin/pltMax for the existing Plot AND
//    wgtMin/wgtMax for the new Gauge. They don't cascade. These are the
//    canonical write-form names (the full plotMin/widgetMin spelling is
//    accepted too, as a declared alias).
project.dataset.update {
  groupId: 0, datasetId: 0,
  pltMin: 0, pltMax: 100,
  wgtMin: 0, wgtMax: 100
}

// 5. Verify the ranges landed (response uses the FULL key names).
project.dataset.getByPath { path: "Engine/Coolant" }
  -> { plotMin: 0, plotMax: 100, widgetMin: 0, widgetMax: 100, ... }

// 6. Pin the Gauge tile.
project.workspace.setCustomizeMode { enabled: true }
project.workspace.addWidget {
  workspaceId: 5001,
  widgetType: "gauge",
  groupId: 0
}

Rule of thumb: **if the user mentions COBS, Modbus, protobuf, CAN,
audio, or "binary", `decoderMethod: 3` is right.** If they mention
NMEA, AT-commands, CSV, line-based, or "text", `decoderMethod: 0` is
right. Hex and Base64 are niche choices for cases where the device
itself ships an encoded payload.

## Common patterns

```js
// CSV (the default)
function parse(frame) { return frame.split(','); }

// Key=value pairs (e.g. "speed=42.1,heading=180")
function parse(frame) {
  const kv = {};
  frame.split(',').forEach(p => {
    const [k, v] = p.split('=');
    kv[k] = v;
  });
  return [kv.speed || 0, kv.heading || 0];
}

// Binary little-endian (decoderMethod 3: frame is an Array of byte values)
function parse(frame) {
  const buf = new Uint8Array(frame.length);
  for (let i = 0; i < frame.length; i++) buf[i] = frame[i];
  const view = new DataView(buf.buffer);
  return [view.getFloat32(0, true), view.getInt16(4, true)];
}
```

## NMEA / hex / domain protocols

For NMEA, AT-commands, hex-encoded, base64, COBS, TLV, MAVLink, UBX,
MessagePack, and more, see `scripts.list{kind: "frame_parser_js"}`: the
codebase ships 28 reference parsers per language for these patterns.
Adapt the closest match.

## Gotchas

```js
// Simple: send a Modbus-shaped command on button click
function transmit() {
  return ":01030000000AF1\r\n";
}

// Slider: send a 16-bit big-endian value
function transmit(value) {
  const v = Math.round(value) & 0xFFFF;
  return new Uint8Array([0xA5, (v >> 8) & 0xFF, v & 0xFF]);
}

// Toggle: send different payload per state
function transmit(checked) {
  return checked ? "RELAY ON\n" : "RELAY OFF\n";
}

// TextField: prepend AT prefix
function transmit(text) {
  return "AT+" + text + "\r\n";
}
```

## Iteration workflow

### Recipe: spectrum analyzer canvas

```js
// Top-level: bootstrap once at compile time
var SAMPLES = 1024;
var ring    = new Array(SAMPLES).fill(0);
var spectrum = new Array(SAMPLES / 2).fill(0);
var head    = 0;

function onFrame() {
  // Cheap: copy the latest sample into the ring
  var v = datasetGetFinal(/*uniqueId*/ 0);
  if (typeof v !== 'number') return;
  ring[head] = v;
  head = (head + 1) % SAMPLES;

// Run FFT on tick (60 Hz default), not on every parsed frame -- a 48 kHz
  // audio source emits 48000 frames/s; we only render ~60/s, so doing
  // FFT here gets us a ~2 kHz redraw rate against a recent window.
  spectrum = computeFFT(ring, head);
}

function paint(ctx, w, h) {
  ctx.fillStyle = theme.widget_base;
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = theme.widget_highlight;
  ctx.beginPath();
  ctx.moveTo(0, h);
  for (var i = 0; i < spectrum.length; ++i) {
    var x = (i / spectrum.length) * w;
    var y = h - spectrum[i] * h;
    ctx.lineTo(x, y);
  }
  ctx.stroke();
}
```

Without `onFrame`, that FFT would run inside `paint` and recompute on
every redraw, including ones triggered by mouse hover and theme
changes. With it, `paint` only laces lines through the cached
`spectrum` array.

## Iteration workflow

40 sequential `project.dataset.update` calls is 40 round-trips AND 40
autosave-debounce restarts. The batch endpoints collapse that into ONE
suspended-autosave window with one final save.

### `project.batch`: exact shape

The parameter is `ops` (NOT `commands`, NOT `mutations`, NOT `requests`).
Each op is `{command: string, params: object}`. Both fields are
required. If you only have `{command, ...}` with params spread at the
top level, the op is rejected.

```json
{
  "ops": [
    {
      "command": "project.dataset.update",
      "params": { "groupId": 0, "datasetId": 0, "title": "LED 1", "index": 1 }
    },
    {
      "command": "project.dataset.update",
      "params": { "groupId": 0, "datasetId": 1, "title": "LED 2", "index": 2 }
    }
  ],
  "stopOnError": false
}
```

## Examples (JavaScript, when Lua won't do)

```js
let ema = 0;
const alpha = 0.2;
function transform(value) {
  ema = alpha * value + (1 - alpha) * ema;
  return ema;
}
```

For ~20 more reference transforms (clamp, dead-zone, ADC-to-voltage,
celsius/fahrenheit, accumulator, autozero, bit extract, ...), call
`scripts.list{kind: "transform_lua"}` or
`scripts.list{kind: "transform_js"}`.

## Frame metadata: second `info` argument

Transforms receive `{frameNumber, sourceId, timestampMs}` as a second arg.
One-arg transforms keep working unchanged (both languages ignore extras).
`timestampMs` is a **monotonic** ms counter (steady clock), not wall
clock. Use it for deltas only.

## Canonical watchdog (connect-cycle safe)

Use `ageMs` instead of bookkeeping arrival times with `Date.now()`: it is computed by the
host from the same monotonic clock that stamps frames, needs no per-script state, and is
immune to reconnect races. Judge silence with `ageMs - mirrorAgeMs`: the copy a script reads
refreshes on the display tick, so a GUI busy with plots adds lag that is not bus silence:

```js
const TIMEOUT_MS  = 1000;
const BOARD_TABLE = "BRD-1";

let commLost = false;

function setup() {
}

function markCommLoss() {
  commLost = true;
  tableSet(BOARD_TABLE, "boot_selftest", 0xFF);
  refreshDashboard();
  notifyCritical("Watchdog", "No frames for over " + TIMEOUT_MS + " ms");
}

function loop() {
  const r = io.getLatestFrame();
  const fresh = r.ok && r.result && r.result.hasData && r.result.ageMs <= TIMEOUT_MS;

if (fresh && commLost) {
    commLost = false;
    notifyInfo("Watchdog", "Communications restored");
  }

if (!fresh && r.ok && r.result && r.result.hasData && !commLost)
    markCommLoss();

delay(100);
}
```

The latest-frame store is cleared on every connect/disconnect edge, so `hasData` is `false`
until the first frame of the **current** connection; the watchdog can never fire from a
previous connection's frame.

# Frame Parser API — JavaScript

A frame parser converts raw bytes (or pre-split text) emitted by a device into
the array of dataset values the dashboard consumes.

## Contract

You define a single function taking exactly **one** parameter:

```js
function parse(frame) {
  // returns Array<number | string>
}
```

## Performance

This function runs on every frame, sometimes at 10+ kHz. Cheap operations:

- `String.prototype.split`
- `parseInt`, `parseFloat`, `Number`
- `String.prototype.match` with a precompiled `RegExp`
- Numeric arithmetic

Avoid:

- Building intermediate objects per call
- Catching exceptions in the hot path — let parse errors bubble; the runtime
  watchdog handles them
- `JSON.parse` on every frame unless the protocol is JSON-line

## Examples

### CSV split (most common)

```js
function parse(frame) {
  return frame.split(',');
}
```

### Tab-delimited with numeric coercion

```js
function parse(frame) {
  const parts = frame.split('\t');
  const out = new Array(parts.length);
  for (let i = 0; i < parts.length; ++i)
    out[i] = parseFloat(parts[i]);
  return out;
}
```

### Regex extraction

```js
const RE = /^\$([A-Z]+),(-?\d+\.\d+),(-?\d+\.\d+),(-?\d+)\*([0-9A-F]{2})/;

function parse(frame) {
  const m = frame.match(RE);
  if (!m)
    return [];
  return [parseFloat(m[2]), parseFloat(m[3]), parseInt(m[4], 10)];
}
```

### JSON-line

```js
function parse(frame) {
  try {
    const obj = JSON.parse(frame);
    return [obj.x, obj.y, obj.z];
  } catch (_e) {
    return [];
  }
}
```

### Binary frame (index the byte array)

With the Binary decoder, `frame` is an `Array` of byte values (0–255), not a
string — string methods throw (`frame.split is not a function`). Index it
directly; wrap it in a `DataView` for multi-byte or float fields:

```js
function parse(frame) {
  if (frame.length < 6)
    return [];
  const view = new DataView(Uint8Array.from(frame).buffer);
  return [view.getFloat32(0, true), view.getInt16(4, true)];
}
```

### Batched samples (one frame yields N rows)

If your device emits multiple sensor rows per frame, return a 2-D array;
the FrameBuilder will flatten to multiple frames.

```js
function parse(frame) {
  const rows = frame.split(';');
  return rows.map(r => r.split(',').map(parseFloat));
}
```

## Device output — `deviceWrite()`

```js
deviceWrite(data, sourceId?) -> { ok: true } | { ok: false, error: "..." }
```

- `data` is a string (UTF-8 encoded on the wire) or an array of byte values
  (0–255).
- `sourceId` is optional; default is the source this parser belongs to.
- Synchronous, fire-and-forget. Never throws. Each call is logged as
  `[deviceWrite] source=N bytes=M written=K`.

Use for closed-loop control from inside `parse()`: ack a frame, raise an
alarm, request a status push. Not for user-triggered actions — those
belong on an Output Widget.

```js
function parse(frame) {
  const values = frame.split(",");
  if (parseFloat(values[0]) > 80) {
    const r = deviceWrite("ALARM=1\n");
    if (!r.ok) console.warn("alarm write failed:", r.error);
  }
  return values;
}
```

Typical use: reset a GPS trace the moment a valid fix arrives so the line from origin to first real sample disappears.

```js
var hadFix = false;
function parse(frame) {
  const [lat, lon, q] = frame.split(",").map(parseFloat);
  if (!hadFix && q > 0) {
    clearPlots();
    hadFix = true;
  }
  return [lat, lon, q];
}
```

These affect the active dashboard window only. They do NOT modify the project file or the user's persisted preferences.

## Errors

Throwing an exception logs a watchdog warning and skips the frame. Returning
non-numeric strings for a numeric dataset coerces via `Number()`; `NaN`
becomes `0`.

## Examples

### Toggle a relay (textual command)

```js
function transmit(value) {
  return value ? "RELAY ON\r\n" : "RELAY OFF\r\n";
}
```

### Slider value over Modbus (built-in helper)

```js
function transmit(value) {
  return modbusWriteRegister(0x0010, Math.round(value));
}
```

### NMEA sentence with inline XOR checksum (no helper exists)

```js
function transmit(value) {
  var body = (typeof value === "string") ? value : "GPCMD," + value;
  var chk = 0;
  for (var i = 0; i < body.length; i++)
    chk ^= body.charCodeAt(i);

var hex = ("0" + chk.toString(16)).slice(-2).toUpperCase();
  return "$" + body + "*" + hex + "\r\n";
}
```

Typical pattern: keep view state in top-level `var`s, mutate it in
`onDrag` / `onWheel`, and read it in `paint`.

```js
var camYaw = 0, camPitch = 0, zoom = 1.0;

function onDrag(x, y, dx, dy) {
  camYaw   += dx * 0.01;
  camPitch += dy * 0.01;
}
function onWheel(x, y, delta) {
  zoom *= (1.0 + delta * 0.1);
  if (zoom < 0.2) zoom = 0.2;
  if (zoom > 5.0) zoom = 5.0;
}
function onDoubleClick(x, y) { camYaw = 0; camPitch = 0; zoom = 1.0; }

function paint(ctx, w, h) {
  // ...draw using camYaw / camPitch / zoom...
}
```

Input handlers fire both on the live dashboard and in the project-editor
preview dialog, so you can test interaction while authoring. A canvas
script with no input handlers behaves exactly as before (events pass through).

// theme -- ThemeManager palette, always in sync with the active theme.
// PRIMARY keys for canvas scripts (these match what the QML dashboard widgets
// already use, so a canvas-rendered widget visually fits the rest of the
// dashboard):
theme.widget_base       // canvas / card background
theme.widget_border     // grid lines, frames, outlines
theme.widget_text       // primary value labels and titles
theme.widget_highlight  // primary signal / value colour
theme.alarm             // red, used for alarm states / second hand / errors
theme.placeholder_text  // muted secondary labels
theme.pane_section_label // small caption text
theme.widget_colors     // ARRAY of per-channel distinct colors, indexable
                        // as theme.widget_colors[i % theme.widget_colors.length]
// Other keys also exist (text, window, base, mid, highlight, accent,
// link, error, groupbox_background, ...) but prefer the widget_* ones
// above for canvas content -- they're tuned for in-widget rendering.

// console -- log/warn/error to the editor status pane
console.log("...")
console.warn("...")
console.error("...")

// Shared-table API (shared with transforms; see "Tables and variables")
tableGet(tableName, registerName)              // -> number | string
tableSet(tableName, registerName, value)       // user-table writes only
datasetGetRaw(uniqueId | "alias")              // raw value of any dataset (string = alias, number = uniqueId)
datasetGetFinal(uniqueId | "alias")            // final value of any dataset

// Closed-loop control APIs (shared with parsers and transforms)
deviceWrite(data, sourceId?)                   // -> { ok, error? }
actionFire(actionId)                           // -> { ok, error? }
checksum(algorithm, data)                      // digest as a binary string (wire order); checksumHex() for hex

Bands may have gaps and may overlap. Severity ≥ Warning posts a
notification when the value enters the band (3-second per-dataset
cooldown suppresses oscillation spam), even when no widget showing
the dataset is visible.

```js
// Find the band a value sits in (linear scan; band counts are tiny)
function bandFor(ds, value) {
  if (!ds.alarmBands) return null;
  for (var i = 0; i < ds.alarmBands.length; i++) {
    var b = ds.alarmBands[i];
    if (value >= b.min && value <= b.max) return b;
  }
  return null;
}

function colorFor(ds, value) {
  var b = bandFor(ds, value);
  if (!b) return theme.widget_highlight;
  if (b.color && b.color.length) return b.color;
  // Severity defaults match the QML widgets' theme palette
  if (b.severity >= 3) return theme.alarm;
  return theme.widget_highlight;
}
```

function paint(ctx, w, h) {
  var speed = datasetGetFinal(SPEED_UID) || 0;
  var rpm   = datasetGetFinal(RPM_UID)   || 0;
  // ...draw using speed and rpm without owning any datasets in this group
}
```

Why not duplicate datasets into the canvas group? Because every dataset
in a project costs a frame-table variable, an exporter column, a
dashboard row, and a project-file entry. Canvas widgets that just READ values
should not own them.

## Tables and variables (the central data bus)

Variables tables let multiple scripts (transforms, canvas scripts) share state.
Two variable types:

For multi-channel canvas widgets (one color per dataset), index into the
`widget_colors` array. The dashboard's plot/multiplot widgets use the
same palette:

```js
const palette = theme.widget_colors;
for (let i = 0; i < datasets.length; i++) {
  ctx.strokeStyle = palette[i % palette.length];
  // ...trace dataset i
}
```

The `theme` global stays in sync when the user switches between light
and dark themes. Hard-coded hex breaks that.

When you do need a literal color (scenery, brand colors), it must be hex
or an SVG name — `rgba(...)` strings are not parsed (see "Style state").
For alpha, Qt hex puts the alpha byte FIRST (`#80FF0000` is 50% red), or
set `ctx.globalAlpha` around the draw. A tiny helper keeps this readable:

```js
function argbHex(a, r, g, b) {
  var s = function(n) { n = Math.round(n); return (n < 16 ? "0" : "") + n.toString(16); };
  return "#" + s(a * 255) + s(r) + s(g) + s(b);
}
ctx.fillStyle = argbHex(0.45, 0, 0, 0);   // 45% black
```

## Worked example 1: progress rings (multi-dataset)

Lays out one circular ring per dataset. Demonstrates a square-ish grid,
arc + moveTo discipline, and a value/title centre.

```js
function paint(ctx, w, h) {
  ctx.fillStyle = theme.widget_base;
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = theme.widget_border;
  ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, w - 2, h - 2);

if (datasets.length === 0) return;

var n    = datasets.length;
  var cols = Math.min(n, Math.max(1, Math.round(Math.sqrt(n * w / h))));
  var rows = Math.ceil(n / cols);
  var pad  = 12;
  var cw   = (w - pad * 2) / cols;
  var ch   = (h - pad * 2) / rows;

for (var i = 0; i < n; i++) {
    var col = i % cols;
    var row = Math.floor(i / cols);
    var cx  = pad + cw * col + cw * 0.5;
    var cy  = pad + ch * row + ch * 0.5 - 6;
    var rr  = Math.max(10, Math.min(cw, ch) * 0.38 - 4);
    var ds  = datasets[i];
    var v   = Number.isFinite(ds.value) ? ds.value : 0;
    var span = (ds.max - ds.min) || 1;
    var norm = Math.max(0, Math.min(1, (v - ds.min) / span));

// Track ring (full circle, the same color the dashboard uses for grid lines).
    ctx.strokeStyle = theme.widget_border;
    ctx.lineWidth   = 12;
    ctx.lineCap     = "butt";
    ctx.beginPath();
    ctx.moveTo(cx + rr, cy);
    ctx.arc(cx, cy, rr, 0, Math.PI * 2);
    ctx.stroke();

// Value arc -- pick a per-channel color from theme.widget_colors so
    // multi-channel canvas widgets use the same palette as multiplots.
    if (norm > 0) {
      var startA = -Math.PI * 0.5;
      var endA   = startA + Math.PI * 2 * norm;
      var palette = theme.widget_colors || [theme.widget_highlight];
      ctx.strokeStyle = palette[i % palette.length];
      ctx.lineCap     = "round";
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(startA) * rr, cy + Math.sin(startA) * rr);
      ctx.arc(cx, cy, rr, startA, endA);
      ctx.stroke();
      ctx.lineCap = "butt";
    }

// Centre value.
    ctx.fillStyle    = theme.widget_text;
    ctx.font         = "bold 18px sans-serif";
    ctx.textAlign    = "center";
    ctx.textBaseline = "middle";
    ctx.fillText((norm * 100).toFixed(0) + "%", cx, cy);

// Title under the ring.
    ctx.fillStyle    = theme.placeholder_text || theme.widget_text;
    ctx.font         = "10px sans-serif";
    ctx.textBaseline = "alphabetic";
    ctx.fillText((ds.title || "").substring(0, 16), cx, cy + rr + 18);
  }

ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";
}
```

## Worked example 2: status grid (peer-dataset reads, no own datasets)

Demonstrates a canvas group with `datasets.length === 0`. The script
reads **peer** datasets by uniqueId (discovered ahead of time via
`project.dataset.list`) and renders a coloured status tile per channel.

```js
// Peer dataset uniqueIds, discovered via project.dataset.list. Each
// constant is set once at script load; edit the script if your project
// layout changes.
var CHANNELS = [
  { uid: 10001, label: "Voltage",   warn: 11.0, alarm: 10.5 },
  { uid: 10002, label: "Current",   warn: 8.0,  alarm: 9.5  },
  { uid: 10003, label: "Temp",      warn: 70,   alarm: 85   },
  { uid: 10004, label: "Pressure",  warn: 110,  alarm: 130  }
];

function tileColor(value, c) {
  if (!Number.isFinite(value)) return theme.widget_border;
  if (value >= c.alarm) return theme.alarm;
  if (value >= c.warn)  return theme.accent;
  return theme.widget_highlight;
}

function paint(ctx, w, h) {
  ctx.fillStyle = theme.widget_base;
  ctx.fillRect(0, 0, w, h);

var pad  = 8;
  var cols = 2;
  var rows = Math.ceil(CHANNELS.length / cols);
  var cw   = (w - pad * (cols + 1)) / cols;
  var ch   = (h - pad * (rows + 1)) / rows;

for (var i = 0; i < CHANNELS.length; i++) {
    var c    = CHANNELS[i];
    var x    = pad + (i % cols) * (cw + pad);
    var y    = pad + Math.floor(i / cols) * (ch + pad);
    var v    = datasetGetFinal(c.uid);

ctx.fillStyle = tileColor(v, c);
    ctx.fillRect(x, y, cw, ch);

ctx.fillStyle    = theme.highlighted_text || theme.widget_text;
    ctx.font         = "bold 14px sans-serif";
    ctx.textAlign    = "left";
    ctx.textBaseline = "top";
    ctx.fillText(c.label, x + 8, y + 8);

ctx.font         = "bold 22px sans-serif";
    ctx.textBaseline = "bottom";
    var label = Number.isFinite(v) ? v.toFixed(1) : "—";
    ctx.fillText(label, x + 8, y + ch - 8);
  }

ctx.textBaseline = "alphabetic";
  ctx.textAlign    = "start";
}
```

## Worked example 3: clock face (zero datasets, frame.timestampMs)

Demonstrates a canvas widget that uses NO dataset at all and just renders
something useful from `frame.timestampMs`.

```js
